 text('分档次',58,501,23,'#173f60','bold');text('经济型',276,501,20);text('中档型',450,501,20);text('高档型',624,501,20);text('豪华型',798,501,20);metrics.forEach(([k,name],i)=>{text(name,58,542+i*41,21,'#667d8e');SEGS.forEach((s,j)=>text(change(delta(get(s,r.period_id),k),k),276+j*174,542+i*41,19))});
